import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = ","
    quotechar = '"'

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=delimiter,
        quotechar=quotechar,
        doublequote=True,
        strict=False,
    )

    try:
        parsed_rows = list(reader)
    except csv.Error:
        parsed_rows = []
        fallback_reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=delimiter,
            quotechar=quotechar,
            doublequote=True,
            strict=False,
        )
        for row in fallback_reader:
            parsed_rows.append(row)

    def nonempty(row):
        return any(str(value).strip() for value in row)

    def looks_like_date(value):
        value = value.strip()
        return bool(
            re.fullmatch(r"\d{1,4}[/-]\d{1,2}[/-]\d{1,4}", value)
            or re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?", value)
        )

    def looks_like_data(value):
        value = value.strip()
        if not value:
            return False
        if looks_like_date(value):
            return True
        if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", value):
            return True
        if re.fullmatch(r"[$€£¥]\s*[-+]?\d+(?:\.\d+)?", value):
            return True
        if re.fullmatch(r"https?://\S+", value, re.IGNORECASE):
            return True
        if re.fullmatch(r"[A-Za-z]{1,8}[-_]\d{2,}", value):
            return True
        return False

    def header_score(row):
        score = 0
        for value in row:
            value = value.strip()
            if not value:
                continue
            if not looks_like_data(value):
                score += 1
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ ./()-]*", value):
                score += 1
        if len(row) == expected_width:
            score += expected_width
        return score

    candidate_index = None
    best_score = -1
    for index, row in enumerate(parsed_rows):
        if not nonempty(row):
            continue
        score = header_score(row)
        if len(row) == expected_width and score > best_score:
            best_score = score
            candidate_index = index
            if score >= expected_width + max(3, expected_width // 2):
                break

    if candidate_index is None:
        for index, row in enumerate(parsed_rows):
            if nonempty(row):
                candidate_index = index
                break

    if candidate_index is None:
        return {"columns": ["" for _ in range(expected_width)], "rows": []}

    raw_header = [str(value) for value in parsed_rows[candidate_index]]
    if raw_header:
        raw_header[0] = raw_header[0].lstrip("\ufeff")

    def preferred_merge_index(columns, row):
        if not columns:
            return len(row) - 1 if row else 0

        semantic_terms = (
            "description",
            "comment",
            "address",
            "detail",
            "title",
            "name",
            "text",
            "note",
            "url",
            "link",
        )
        candidates = []
        for index, column in enumerate(columns):
            normalized = re.sub(r"[^a-z0-9]+", "", column.lower())
            score = 0
            for term in semantic_terms:
                if term in normalized:
                    score += 10
            if index < len(row) and row[index].strip():
                if not looks_like_data(row[index]):
                    score += 1
            candidates.append((score, index))

        candidates.sort(key=lambda item: (item[0], item[1]))
        return candidates[-1][1] if candidates else len(row) - 1

    def fit_row(row, columns):
        values = [str(value) for value in row]
        if len(values) == expected_width:
            return values
        if len(values) < expected_width:
            return values + [""] * (expected_width - len(values))

        merge_index = preferred_merge_index(columns, values)
        extra_count = len(values) - expected_width
        end = merge_index + extra_count + 1
        merged = ",".join(values[merge_index:end])
        fitted = values[:merge_index] + [merged] + values[end:]
        if len(fitted) < expected_width:
            fitted.extend([""] * (expected_width - len(fitted)))
        elif len(fitted) > expected_width:
            fitted = fitted[:expected_width - 1] + [",".join(fitted[expected_width - 1:])]
        return fitted

    columns = fit_row(raw_header, [])
    data_rows = []

    for row in parsed_rows[candidate_index + 1:]:
        if not nonempty(row):
            continue
        data_rows.append(fit_row(row, columns))

    return {"columns": columns, "rows": data_rows}
